// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    Reverter r;

    function setUp() public {
        c = new Proxy();
        r = new Reverter();
    }

    function testFuzz_property(bytes memory data) public {
        bool ok;
        try c.forward(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false, "forward to a reverting callee must revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
